import bisect, random
# What each index type can serve: B+ tree = sorted keys (bisect); hash = dict of buckets
supports={'B+':{'eq','range','join'}, 'hash':{'eq','join'}}
preds={'Movie.CustomerRating':'range',          # > 3.4
       'Genre.Name':'eq',                        # = "Comedy"
       'Movie_Genre.MovieID':'join','Movie.ID':'join',
       'Movie_Genre.GenreID':'join','Genre.ID':'join'}
def scheme(special=None, kind=None, rest='B+'):
    return {a:(kind if a==special else rest) for a in preds}
opts={'A':scheme(),'B':scheme('Genre.Name','hash'),
      'C':scheme('Movie.CustomerRating','hash'),'D':scheme(rest='hash')}
for k,sch in opts.items():
    unusable=[a for a,t in sch.items() if preds[a] not in supports[t]]
    print(k,'every index usable by its predicate:',not unusable, unusable)
# A True, B True, C False ['Movie.CustomerRating'], D False ['Movie.CustomerRating'] -> A;B
# Demo: range 'rating > 3.4' via sorted index (B+ leaf order) vs hash index
random.seed(1); ratings=[round(random.uniform(0,5),1) for _ in range(10000)]
srt=sorted(ratings); i=bisect.bisect_right(srt,3.4)
hashidx={}
for r in ratings: hashidx.setdefault(hash(r)%97,[]).append(r)   # buckets in hash order, not value order
hits_hash=[r for b in hashidx.values() for r in b if r>3.4]     # must visit every bucket
print('sorted index: start at position',i,'and read',len(srt)-i,'keys; hash: visited',
      sum(len(b) for b in hashidx.values()),'keys; same answer:',len(srt)-i==len(hits_hash))
